def edge_index(u, v, n=15):
    if u > v:
        u, v = v, u
    # Number of edges before row u: sum_{i=0}^{u-1} (n - 1 - i)
    # = u * (n - 1) - u * (u - 1) // 2
    # Then add v - u - 1
    return u * (n - 1) - u * (u - 1) // 2 + (v - u - 1)

edges = [(0, 5), (0, 6), (0, 10), (1, 8), (1, 9), (2, 8), (3, 8), (4, 8), (7, 8), (8, 11), (8, 12), (8, 13), (8, 14)]
sol = [0] * 105
for u, v in edges:
    sol[edge_index(u, v)] = 1

print(sol)
print("Indices of 1s:", [i for i, x in enumerate(sol) if x == 1])
for u, v in edges:
    print(f"({u}, {v}) -> {edge_index(u, v)}")
